import{_ as i,o as s,c as o,m as n,e as l,k as a,w as r,f as c,l as d}from"./index-BWdS9fSP.js";const p={},m={class:"min-h-screen pt-32 pb-20 px-6 max-w-4xl mx-auto text-white"},u={class:"mt-12 text-center"};function h(x,e){const t=d("router-link");return s(),o("div",m,[e[1]||(e[1]=n('<h1 class="text-4xl font-bold mb-8">Environmental Policy</h1><div class="space-y-8 text-neutral-300 leading-relaxed"><div class="p-4 bg-emerald-500/10 border border-emerald-500/30 rounded-xl"><p class="text-emerald-400 font-medium">Sustainability is core to our business. We aim to minimise environmental impact while providing excellent IT services.</p></div><section><h2 class="text-2xl font-bold text-white mb-4">1. Our Commitment</h2><p>Jake Fieldhouse Consulting Ltd is committed to operating in an environmentally responsible manner. We aim to:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Minimise waste sent to landfill from our operations</li><li>Promote the reuse and refurbishment of IT equipment</li><li>Ensure responsible recycling of materials that cannot be reused</li><li>Comply with all applicable environmental legislation</li><li>Continuously improve our environmental performance</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">2. Regulatory Compliance</h2><p>We operate in compliance with:</p><ul class="list-disc list-inside space-y-2 mt-4"><li><strong class="text-white">Environmental Protection Act 1990:</strong> Duty of care for waste handling</li><li><strong class="text-white">Waste Electrical and Electronic Equipment (WEEE) Regulations 2013:</strong> Proper treatment and recycling of e-waste</li><li><strong class="text-white">Hazardous Waste Regulations 2005:</strong> Safe handling of hazardous components</li></ul><div class="mt-4 p-4 bg-neutral-800 rounded-xl"><p class="text-sm text-neutral-400">Environment Agency Registration</p><p class="font-bold text-white text-lg">CBDL620098</p><p class="text-sm text-neutral-500">Upper Tier Waste Carrier</p><a href="https://environment.data.gov.uk/public-register/view/search-waste-carriers-brokers" target="_blank" rel="noopener" class="text-blue-400 hover:underline text-sm">Verify on Public Register →</a></div></section><section><h2 class="text-2xl font-bold text-white mb-4">3. E-Waste Handling</h2><p>Our e-waste collection service follows these principles:</p><ul class="list-disc list-inside space-y-2 mt-4"><li><strong class="text-white">Reuse First:</strong> Working equipment is refurbished for resale or donation where possible</li><li><strong class="text-white">Responsible Recycling:</strong> Non-working items are dismantled and recycled through approved WEEE facilities</li><li><strong class="text-white">Zero Landfill Target:</strong> We aim to divert 100% of collected e-waste from landfill</li><li><strong class="text-white">Data Destruction:</strong> All storage media is sanitised to NIST 800-88 standards before recycling</li></ul><p class="mt-4 text-sm text-neutral-500">Note: &quot;Zero landfill&quot; is an aspirational target. A small percentage of materials may be disposed of via approved waste streams when recycling is not technically feasible.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">4. Office Operations</h2><p>We aim to reduce our environmental footprint by:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Using digital documentation to reduce paper waste</li><li>Prioritising remote support to reduce travel emissions where appropriate</li><li>Using energy-efficient equipment in our workshop</li><li>Recycling consumables and packaging materials</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">5. Continuous Improvement</h2><p>We are committed to reviewing and improving our environmental practices. This policy is reviewed annually and updated as our operations evolve.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">6. Contact</h2><p>For questions about our environmental practices, contact <a href="mailto:jake@jakefieldhouse.co.uk" class="text-blue-400 hover:underline">jake@jakefieldhouse.co.uk</a>.</p></section><p class="text-neutral-500 text-sm pt-8">Last updated: January 2026</p></div>',2)),l("div",u,[a(t,{to:"/",class:"text-neutral-500 hover:text-white transition-colors"},{default:r(()=>[...e[0]||(e[0]=[c("← Back to Home",-1)])]),_:1})])])}const f=i(p,[["render",h]]);export{f as default};
